package verifygate

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// A generator's source, a shipped template's original, and a script with a
// header in a heredoc mention "generated" and "do not edit" without being
// generated; generated stubs are known by their names.
func TestGenerated_HeadersInSourcesAreNotGenerated(t *testing.T) {
	root := t.TempDir()
	files := map[string]string{
		"pkg/gen/workflow_generate.go": "package gen\n\nconst header = \"// Code is generated by gen. DO NOT EDIT.\"\nconst generatedJSHeader = \"do not edit\"\n",
		"stop_gate/gate.ts":            "// Generated by Autopus-ADK. Do not edit\nexport const x = 1\n",
		"scripts/render.sh":            "#!/bin/sh\ncat <<EOF\n# generated file, do not edit\nEOF\n",
		"svc/a_pb2_grpc.py":            "# Generated by the gRPC Python protocol compiler plugin. DO NOT EDIT!\nx = 1\n",
		"api/types.pb.go":              "package api\n",
		"lib/model.g.dart":             "class A {}\n",
		"gen/real.go":                  "// Code generated by tool. DO NOT EDIT.\n\npackage gen\n",
	}
	for f, body := range files {
		p := filepath.Join(root, filepath.FromSlash(f))
		require.NoError(t, os.MkdirAll(filepath.Dir(p), 0o755))
		require.NoError(t, os.WriteFile(p, []byte(body), 0o644))
	}
	for _, f := range []string{"pkg/gen/workflow_generate.go", "stop_gate/gate.ts", "scripts/render.sh"} {
		assert.True(t, IsProductSource(root, f), f)
	}
	for _, f := range []string{"svc/a_pb2_grpc.py", "api/types.pb.go", "lib/model.g.dart", "gen/real.go"} {
		assert.False(t, IsProductSource(root, f), f)
	}
}
